'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/menu/md-gb-menu.js';
import '@material/web/labs/gb/components/menu/md-gb-menu-group.js';
import '@material/web/labs/gb/components/menu/md-gb-menu-item.js';
import {MenuElement} from '@material/web/labs/gb/components/menu/menu-element.js';
import {MenuGroupElement} from '@material/web/labs/gb/components/menu/menu-group-element.js';
import {MenuItemElement} from '@material/web/labs/gb/components/menu/menu-item-element.js';

/**
 * A Material Design component. Wraps <md-gb-menu>.
 * Docs: https://material-web.dev/3.0/components/menu/
 */
export const MdMenu = createComponent({
  react: React,
  tagName: 'md-gb-menu',
  elementClass: MenuElement,
});

export type MdMenuProps = React.ComponentProps<typeof MdMenu>;

/**
 * A Material Design component. Wraps <md-gb-menu-group>.
 * Docs: https://material-web.dev/3.0/components/menu/
 */
export const MdMenuGroup = createComponent({
  react: React,
  tagName: 'md-gb-menu-group',
  elementClass: MenuGroupElement,
});

export type MdMenuGroupProps = React.ComponentProps<typeof MdMenuGroup>;

/**
 * A Material Design component. Wraps <md-gb-menu-item>.
 * Docs: https://material-web.dev/3.0/components/menu/
 */
export const MdMenuItem = createComponent({
  react: React,
  tagName: 'md-gb-menu-item',
  elementClass: MenuItemElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdMenuItemProps = React.ComponentProps<typeof MdMenuItem>;
